/* Unaligned loads with endianness conversion */

static forceinline u16
get_unaligned_le16(const u8 *p)
{
        if (UNALIGNED_ACCESS_IS_FAST)
                return le16_bswap(load_u16_unaligned(p));
        else
                return ((u16)p[1] << 8) | p[0];
}

static forceinline u16
